-- STEP 1: CLEAN EXISTING ATTENDANCE & PARTICIPANTS
TRUNCATE TABLE attendance, participant_event_selections CASCADE;
DELETE FROM participants;

-- STEP 2: ENSURE 5 OFFICIAL EVENTS EXIST
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;

-- STEP 3: ENSURE DEFAULT COORDINATORS EXIST
ON CONFLICT (coordinator_code) DO NOTHING;

-- STEP 4: INSERT ALL 128 MASTER PARTICIPANTS

-- STEP 5: VERIFICATION
SELECT count(*) AS total_participants_in_db FROM participants;